"""Codex Dispatch — unified dispatch grammar for workspace interaction.

Phase B of the Codex Layer. Routes all input through:
  - Bare coords    → codex engine      (t5, e1t5, e0)
  - Prefix .       → render verbs      (.d, .a, .v1)
  - Prefix !       → shell passthrough (!git status)
  - Pipe |>        → output chaining   (e0 |> _.p1)
  - Prefix _       → result register   (_, _1, _.status)
  - No prefix      → interceptor check (Phase C) then shell fallback

FLAG-2 FIX: Uses |> for pipes (not ' > ') to avoid shell redirect collision.
             ! prefix checked BEFORE pipe splitting to prevent misrouting.

Pipeline: build-codex-layer-v1
"""

from __future__ import annotations

import re
import subprocess
from pathlib import Path
from typing import Optional

from codex_output_codec import CodexResult, ResultRegister, output_to_codex

# Coordinate grammar regex (matches codex coordinate patterns)
COORD_RE = re.compile(r'^(md|mw|lm|[a-z])\d*$', re.IGNORECASE)

# Extended: match e{n}{coord} compounds (e1t6, e0p3) + bare coords (t5, lm3, d1-d5)
EXTENDED_COORD_RE = re.compile(
    r'^(?:e\d+(?:(?:md|mw|[a-z])\d*)?|(?:md|mw|lm|[a-z])\d*(?:-(?:md|mw|lm|[a-z])?\d+)?)$',
    re.IGNORECASE,
)

# Render verb patterns
RENDER_RE = re.compile(r'^\.[a-z]')

# Pipe operator (FLAG-2: |> not ' > ')
PIPE_OP = '|>'


class CodexDispatcher:
    """Unified dispatch for all workspace interaction."""

    def __init__(self, workspace: Path):
        self.workspace = workspace
        self.register = ResultRegister(workspace)
        self.interceptor = None  # set by Phase C

    def dispatch(self, input_str: str) -> CodexResult:
        """Route input through the dispatch grammar.

        Order (FLAG-2 fix: ! checked before pipes):
        1. Shell passthrough: ! prefix (BEFORE pipe check)
        2. Pipe chains: |> operator
        3. Render verbs: . prefix
        4. Result register: _ prefix
        5. Coordinate resolution: matches coord grammar
        6. Interceptor check (Phase C)
        7. Fallback: execute as shell
        """
        input_str = input_str.strip()
        if not input_str:
            return CodexResult(source='empty', rendered='(empty input)')

        # 1. Shell passthrough — checked FIRST, before pipe splitting
        #    This prevents !git log > file.txt from being misrouted
        if input_str.startswith('!'):
            return self._dispatch_shell(input_str[1:])

        # 2. Pipe chains: split on |> and execute sequentially
        if PIPE_OP in input_str:
            return self._dispatch_pipe(input_str)

        # 3. Render verbs: . prefix
        if RENDER_RE.match(input_str):
            return self._dispatch_render(input_str)

        # 4. Result register: _ prefix
        if input_str.startswith('_'):
            return self._dispatch_register(input_str)

        # 5. Coordinate resolution: matches coord grammar
        first_token = input_str.split()[0]
        if EXTENDED_COORD_RE.match(first_token):
            return self._dispatch_coord(input_str)

        # 6. Interceptor check (Phase C)
        if self.interceptor:
            redirect = self.interceptor.check(input_str)
            if redirect:
                return redirect

        # 7. Fallback: shell execution
        return self._dispatch_shell(input_str)

    def _dispatch_pipe(self, input_str: str) -> CodexResult:
        """Chain commands via |> operator. Previous result available as _."""
        parts = [p.strip() for p in input_str.split(PIPE_OP)]
        result = None
        for part in parts:
            if not part:
                continue
            # Substitute _ references from previous result
            if result:
                part = self._substitute_register_refs(part, result)
            result = self.dispatch(part)
            self.register.push(result)
        return result or CodexResult(source='pipe', rendered='(empty pipe)')

    def _dispatch_shell(self, command: str) -> CodexResult:
        """Execute shell command and run output through codec."""
        command = command.strip()
        try:
            proc = subprocess.run(
                command, shell=True,
                capture_output=True, text=True,
                cwd=str(self.workspace),
                timeout=30,
            )
            result = output_to_codex(command, proc.stdout, proc.stderr, proc.returncode)
            if proc.returncode != 0 and proc.stderr:
                result.rendered += f'\n[exit {proc.returncode}] {proc.stderr[:200]}'
            self.register.push(result)
            return result
        except subprocess.TimeoutExpired:
            return CodexResult(
                source=command, content_type='text',
                rendered=f'[timeout after 30s] {command}',
            )
        except Exception as e:
            return CodexResult(
                source=command, content_type='text',
                rendered=f'[error] {e}',
            )

    def _dispatch_render(self, input_str: str) -> CodexResult:
        """Route render verb to codex engine."""
        return self._dispatch_coord(input_str)

    def _dispatch_register(self, input_str: str) -> CodexResult:
        """Resolve result register reference."""
        # Field access: _.status, _2.p1
        if '.' in input_str:
            val = self.register.resolve_field(input_str)
            if val is not None:
                return CodexResult(
                    coord=input_str, source='register',
                    content_type='text', fields={'value': val},
                    rendered=val,
                )
        # Bare register: _, _1
        result = self.register.resolve(input_str)
        if result:
            return result
        return CodexResult(
            source='register', content_type='text',
            rendered=f'Register {input_str} is empty',
        )

    def _dispatch_coord(self, input_str: str) -> CodexResult:
        """Route coordinate to codex_engine."""
        try:
            proc = subprocess.run(
                ['python3', 'scripts/codex_engine.py'] + input_str.split(),
                capture_output=True, text=True,
                cwd=str(self.workspace),
                timeout=10,
            )
            result = output_to_codex(
                f'codex_engine.py {input_str}',
                proc.stdout, proc.stderr, proc.returncode,
            )
            self.register.push(result)
            return result
        except Exception as e:
            return CodexResult(
                source=input_str, content_type='text',
                rendered=f'[coord error] {e}',
            )

    def _substitute_register_refs(self, text: str, prev: CodexResult) -> str:
        """Replace _ references in text with values from previous result."""
        # _.field references
        def replace_field(m):
            field_name = m.group(1)
            val = prev.fields.get(field_name, m.group(0))
            return str(val)

        text = re.sub(r'_\.(\w+)', replace_field, text)
        # Bare _ → previous rendered output (first line)
        # Only substitute standalone _ (not inside identifiers like _my_var)
        if '_' in text and not re.search(r'_\.\w', text):
            first_line = prev.rendered.split('\n')[0] if prev.rendered else ''
            text = re.sub(r'(?<!\w)_(?!\w)', first_line, text)
        return text


# ── CLI entry point ─────────────────────────────────────────────────────────

if __name__ == '__main__':
    import sys
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.home() / '.openclaw' / 'workspace'
    dispatcher = CodexDispatcher(workspace)

    if len(sys.argv) > 2:
        result = dispatcher.dispatch(' '.join(sys.argv[2:]))
        print(result.rendered)
    else:
        print('Usage: codex_dispatch.py <workspace> <command>')
        print('  e.g.: codex_dispatch.py /path/to/workspace "t5"')
        print('  e.g.: codex_dispatch.py /path/to/workspace "!git status"')
        print('  e.g.: codex_dispatch.py /path/to/workspace "e0 |> _.p1"')

"""Codex Output Codec — transforms command outputs into coordinate-addressed results.

Phase A of the Codex Layer. Provides:
  - Output recognition pipeline (JSON → table → KV → raw)
  - Known script parsers for top workspace scripts
  - Result register with transient coordinates (_, _1, _2, ...)
  - Dot notation field access (_.status, _.p1)

Register state persists per-workspace at {workspace}/.codex_runtime/register.json
(FLAG-1: scoped per-workspace, not HOME, to avoid cross-agent clobber).

Pipeline: build-codex-layer-v1
"""

from __future__ import annotations

import json
import re
import time
from collections import deque
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Optional, Dict, List, Any


# ── Data model ──────────────────────────────────────────────────────────────

@dataclass
class CodexResult:
    """A coordinate-addressed result from any command execution."""
    coord: str = '_'          # transient coord: "_" (latest), "_1", "_2"
    source: str = ''          # what generated it: "e0", "!git status", "t5"
    content_type: str = 'text'  # 'table' | 'json' | 'kv' | 'text' | 'codex'
    fields: Dict[str, Any] = field(default_factory=dict)
    raw: str = ''             # original output
    rendered: str = ''        # codex-formatted output
    timestamp: float = 0.0    # epoch seconds (for TTL — S2)

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict) -> 'CodexResult':
        return cls(**{k: v for k, v in d.items() if k in cls.__dataclass_fields__})


# ── Result Register ─────────────────────────────────────────────────────────

REGISTER_TTL_SECONDS = 300  # 5 minutes — auto-expire stale entries (S2)

class ResultRegister:
    """Transient coordinate stack for command outputs.

    Persists to {workspace}/.codex_runtime/register.json for cross-process access.
    """

    def __init__(self, workspace: Path, max_history: int = 5):
        self.workspace = workspace
        self._stack: deque[CodexResult] = deque(maxlen=max_history)
        runtime_dir = workspace / '.codex_runtime'
        runtime_dir.mkdir(exist_ok=True)
        self._state_file = runtime_dir / 'register.json'
        self._load()

    def push(self, result: CodexResult) -> str:
        """Push result, return its transient coordinate."""
        result.timestamp = time.time()
        self._stack.appendleft(result)
        self._reassign_coords()
        self._persist()
        return '_'

    def resolve(self, coord: str) -> Optional[CodexResult]:
        """Resolve _ or _N. Returns None if expired or missing."""
        self._expire_stale()
        if coord == '_':
            return self._stack[0] if self._stack else None
        m = re.match(r'^_(\d+)$', coord)
        if m:
            idx = int(m.group(1))
            return self._stack[idx] if idx < len(self._stack) else None
        return None

    def resolve_field(self, coord: str) -> Optional[str]:
        """Resolve _.field or _N.field."""
        parts = coord.split('.', 1)
        result = self.resolve(parts[0])
        if result and len(parts) > 1:
            val = result.fields.get(parts[1])
            return str(val) if val is not None else None
        return None

    def show(self) -> str:
        """Render register state for context injection."""
        self._expire_stale()
        if not self._stack:
            return ''
        lines = []
        for r in self._stack:
            age = int(time.time() - r.timestamp) if r.timestamp else 0
            fields_str = ', '.join(f'{k}={v}' for k, v in list(r.fields.items())[:5])
            lines.append(f'{r.coord}  [{r.content_type}]  src={r.source}  age={age}s  {fields_str}')
        return '\n'.join(lines)

    def clear(self):
        """Clear all register entries (S1: --register-clear)."""
        self._stack.clear()
        self._persist()

    def _reassign_coords(self):
        for i, r in enumerate(self._stack):
            r.coord = '_' if i == 0 else f'_{i}'

    def _expire_stale(self):
        now = time.time()
        while self._stack and (now - self._stack[-1].timestamp > REGISTER_TTL_SECONDS):
            self._stack.pop()
        self._reassign_coords()

    def _persist(self):
        try:
            data = [r.to_dict() for r in self._stack]
            self._state_file.write_text(json.dumps(data, default=str), encoding='utf-8')
        except Exception:
            pass  # non-critical — register is transient

    def _load(self):
        try:
            if self._state_file.exists():
                data = json.loads(self._state_file.read_text(encoding='utf-8'))
                for d in data:
                    self._stack.append(CodexResult.from_dict(d))
                self._expire_stale()
        except Exception:
            pass  # corrupted or missing — start fresh


# ── Output Recognition ──────────────────────────────────────────────────────

def _looks_like_json(text: str) -> bool:
    stripped = text.strip()
    return (stripped.startswith('{') and stripped.endswith('}')) or \
           (stripped.startswith('[') and stripped.endswith(']'))


def _looks_like_table(text: str) -> bool:
    """Detect aligned columns (2+ spaces between fields) or TSV."""
    lines = [l for l in text.strip().splitlines() if l.strip()]
    if len(lines) < 2:
        return False
    # Check if most lines have consistent column-like spacing
    multi_space = sum(1 for l in lines if re.search(r'  \S', l))
    return multi_space > len(lines) * 0.5


def _looks_like_kv(text: str) -> bool:
    """Detect key: value or key=value patterns."""
    lines = [l for l in text.strip().splitlines() if l.strip()]
    if len(lines) < 2:
        return False
    kv_count = sum(1 for l in lines if re.match(r'^\s*\S+\s*[:=]\s*\S', l))
    return kv_count > len(lines) * 0.5


# ── Known Script Parsers ────────────────────────────────────────────────────

_KNOWN_SCRIPTS = [
    (re.compile(r'codex_engine\.py\s+--supermap'), '_parse_supermap'),
    (re.compile(r'pipeline_update\.py\s+(\S+)\s+show'), '_parse_pipeline_show'),
    (re.compile(r'pipeline_orchestrate\.py'), '_parse_orchestrate'),
    (re.compile(r'log_memory\.py'), '_parse_log_memory'),
    (re.compile(r'codex_engine\.py\s+([a-z]\S*)'), '_parse_coord_nav'),
]


def _parse_supermap(command: str, stdout: str) -> CodexResult:
    """Parse supermap output into addressable fields."""
    fields: Dict[str, Any] = {}
    # Extract namespace counts: ╶─ p   pipelines (3)
    for m in re.finditer(r'╶─\s+(\w+)\s+\S+\s+\((\d+)\)', stdout):
        fields[f'{m.group(1)}_count'] = int(m.group(2))
    # Extract individual entries: │  ╶─ p1    slug  summary
    for m in re.finditer(r'╶─\s+([a-z]+\d+)\s+(\S+)', stdout):
        fields[m.group(1)] = m.group(2)
    return CodexResult(
        source='e0 --supermap', content_type='codex',
        fields=fields, raw=stdout, rendered=stdout[:500],
    )


def _parse_pipeline_show(command: str, stdout: str) -> CodexResult:
    fields: Dict[str, Any] = {}
    # Status line
    sm = re.search(r'Status:\s*(\S+)', stdout)
    if sm:
        fields['status'] = sm.group(1)
    # Pending action
    pm = re.search(r'pending_action\s*→\s*(\S+)', stdout)
    if pm:
        fields['pending'] = pm.group(1)
    return CodexResult(
        source=command, content_type='codex',
        fields=fields, raw=stdout, rendered=stdout[:500],
    )


def _parse_orchestrate(command: str, stdout: str) -> CodexResult:
    fields: Dict[str, Any] = {}
    rm = re.search(r'Completed:\s*(\S+)', stdout)
    if rm:
        fields['result'] = rm.group(1)
    nm = re.search(r'Next:\s*(\S+)', stdout)
    if nm:
        fields['next_agent'] = nm.group(1)
    return CodexResult(
        source=command, content_type='codex',
        fields=fields, raw=stdout, rendered=stdout[:500],
    )


def _parse_log_memory(command: str, stdout: str) -> CodexResult:
    fields: Dict[str, Any] = {}
    em = re.search(r'Entry:\s*(\S+)', stdout)
    if em:
        fields['entry'] = em.group(1)
    dm = re.search(r'Daily:\s*(\S+)', stdout)
    if dm:
        fields['daily'] = dm.group(1)
    return CodexResult(
        source=command, content_type='codex',
        fields=fields, raw=stdout, rendered=stdout[:300],
    )


def _parse_coord_nav(command: str, stdout: str) -> CodexResult:
    """Parse coordinate navigation output."""
    fields: Dict[str, Any] = {}
    # Extract frontmatter key-value pairs
    for m in re.finditer(r'^(\w+):\s+(.+)$', stdout, re.MULTILINE):
        fields[m.group(1)] = m.group(2).strip()
    return CodexResult(
        source=command, content_type='codex',
